# Calculate average spend per user for each segment
results = {}
segments = ['budget', 'standard', 'premium', 'enterprise']
data = {
    'budget': {'users': 1200, 'spend': 36000},
    'standard': {'users': 800, 'spend': 48000},
    'premium': {'users': 300, 'spend': 36000},
    'enterprise': {'users': 100, 'spend': 25000}
}

for seg, vals in data.items():
    avg = vals['spend'] / vals['users']
    results[seg] = avg
    print(f"{seg}: {vals['spend']} / {vals['users']} = {avg:.2f}")

max_seg = max(results, key=results.get)
print(f"\nHighest: {max_seg} with average spend per user = {results[max_seg]:.2f}")

